css:
.loader { display: inline-flex; align-items: center; justify-content: space-between; width: var(--loader-size); height: calc(var(--loader-size) * .6); }
.loader span { width: calc(var(--loader-size) * .12); height: 100%; border-radius: 9999px; background: linear-gradient(to top, var(--loader-color), var(--loader-secondary-color)); animation: twEq calc(var(--loader-speed) * 1.1) ease-in-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .12); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .24); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .36); }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * .48); }
@keyframes twEq { 0%, 100% { transform: scaleY(.25); } 50% { transform: scaleY(1); } }

tailwind:
{/* keyframes twEq: 0%,100% { scaleY(.25) } 50% { scaleY(1) } */}
<div className="inline-flex h-10 w-16 items-center justify-between">
  {[0, 120, 240, 360, 480].map((delay) => (
    <span
      key={delay}
      className="h-full w-2 animate-[twEq_1.1s_ease-in-out_infinite] rounded-full bg-gradient-to-t from-fuchsia-500 to-indigo-500"
      style={{ animationDelay: delay + "ms" }}
    />
  ))}
</div>
